import os
import sys
import ast
import subprocess
import tempfile
import shutil
import time
import re
import tomllib
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Tuple

# Import dependencies as per contract
try:
    from hae.evaluation.artifacts import filter_bundle
except ImportError:
    # Fallback for isolated testing if artifacts module is not yet available in path
    def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
        return bundle

SKIPPED = 'skipped'
PASSED = 'passed'
FAILED = 'failed'
DEFAULT_PENALTY_PER_GATE = 6.25
DEFAULT_TIMEOUT_S = 60

@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED

@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        return len(self.passed_gates) / len(evaluated)

    def summary(self) -> str:
        passed = len(self.passed_gates)
        evaluated = len(self.evaluated_gates)
        return f"{passed}/{evaluated} gates passed"

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [g.__dict__ for g in self.gates],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version
        }

def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    if not text:
        return {}

    # Regex to match fenced code blocks with optional language and filename hint
    # Matches ```python\n...``` or ```path/to/file.py\n...```
    pattern = r"```(?:python|py)?\s*(?:\n|^)(.*?)(?:\n|^)```"
    matches = re.findall(pattern, text, re.DOTALL)

    bundle = {}
    for i, content in enumerate(matches):
        # Try to guess a filename if not provided in the fence
        # Simple heuristic: use index if no clear path
        path = f"extracted_block_{i}.py"
        # Check if the first line looks like a path comment or shebang? 
        # The spec says "Recovers a path->content map". 
        # Usually fenced blocks don't carry paths unless specified like ```python:file.py
        # Let's stick to simple extraction for now, assuming the harness handles naming or 
        # the blocks are just code.
        bundle[path] = content

    return bundle

class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int = DEFAULT_TIMEOUT_S, penalty_per_gate: float = DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str] = None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any = None, deliverable_text: str = '') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = {}
        if workspace is not None:
            try:
                if hasattr(workspace, 'export_bundle'):
                    bundle = workspace.export_bundle()
                elif isinstance(workspace, dict):
                    bundle = workspace
            except Exception:
                bundle = {}

        if not bundle and deliverable_text:
            bundle = extract_code_blocks(deliverable_text)

        return self.verify_bundle(bundle, source='workspace')

    def verify_bundle(self, bundle: Dict[str, str], source: str = 'bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        filtered_bundle = filter_bundle(bundle)

        if not filtered_bundle:
            # Empty workspace fails everything evaluable
            gates = [
                GateResult(name='syntax', status=FAILED, method='ast', detail='No python files found'),
                GateResult(name='build', status=FAILED, method='fs', detail='No build metadata found'),
                GateResult(name='smoke', status=FAILED, method='subprocess', detail='No modules to import'),
                GateResult(name='tests', status=FAILED, method='subprocess', detail='No test files found'),
                GateResult(name='telemetry', status=FAILED, method='ast', detail='No telemetry instrumentation found'),
            ]
            return VerificationReport(
                gates=gates,
                score_penalty=len(gates) * self.penalty_per_gate,
                authored_files=0,
                python_files=0,
                source=source
            )

        with tempfile.TemporaryDirectory() as tmpdir:
            # Write bundle to disk
            for path, content in filtered_bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            return self.verify_directory(tmpdir, authored=filtered_bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]] = None, source: str = 'directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        if authored is None:
            # Scan directory
            authored = {}
            for root, dirs, files in os.walk(workdir):
                # Skip hidden and common junk dirs
                dirs[:] = [d for d in dirs if not d.startswith('.') and d not in ('__pycache__', 'venv', '.venv')]
                for file in files:
                    if file.endswith('.py') or file in ('pyproject.toml', 'setup.py', 'setup.cfg'):
                        rel_path = os.path.relpath(os.path.join(root, file), workdir)
                        try:
                            with open(os.path.join(root, file), 'r', encoding='utf-8') as f:
                                authored[rel_path] = f.read()
                        except Exception:
                            pass

        # Filter again just in case
        authored = filter_bundle(authored)

        python_files = [p for p in authored if p.endswith('.py')]

        gates = []

        # 1. Syntax Gate
        gates.append(self._gate_syntax(python_files, authored))

        # 2. Build Gate
        gates.append(self._gate_build(workdir, authored))

        # 3. Smoke Gate
        gates.append(self._gate_smoke(workdir, python_files, authored))

        # 4. Tests Gate
        gates.append(self._gate_tests(workdir, python_files, authored))

        # 5. Telemetry Gate
        gates.append(self._gate_telemetry(python_files, authored))

        failed_count = sum(1 for g in gates if g.status == FAILED)
        score_penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=score_penalty,
            authored_files=len(authored),
            python_files=len(python_files),
            source=source
        )

    def _gate_syntax(self, python_files: List[str], authored: Dict[str, str]) -> GateResult:
        start = time.time()
        if not python_files:
            return GateResult(name='syntax', status=FAILED, method='ast', detail='No python files found', duration_s=time.time()-start)

        errors = []
        for path in python_files:
            content = authored[path]
            try:
                ast.parse(content, filename=path)
            except SyntaxError as e:
                errors.append(f"{path}: {e}")

        duration = time.time() - start
        if errors:
            return GateResult(name='syntax', status=FAILED, method='ast', detail='; '.join(errors), duration_s=duration)
        return GateResult(name='syntax', status=PASSED, method='ast', detail='All files parse', duration_s=duration)

    def _gate_build(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Check for metadata files
        has_pyproject = 'pyproject.toml' in authored
        has_setup_py = 'setup.py' in authored
        has_setup_cfg = 'setup.cfg' in authored

        if not (has_pyproject or has_setup_py or has_setup_cfg):
            return GateResult(name='build', status=FAILED, method='fs', detail='No build metadata (pyproject.toml, setup.py, setup.cfg) found', duration_s=time.time()-start)

        # Validate pyproject.toml if present
        if has_pyproject:
            try:
                data = tomllib.loads(authored['pyproject.toml'])
                if not any(k in data for k in ('project', 'build-system', 'tool')):
                    return GateResult(name='build', status=FAILED, method='tomllib', detail='pyproject.toml lacks [project], [build-system], or [tool]', duration_s=time.time()-start)
            except Exception as e:
                return GateResult(name='build', status=FAILED, method='tomllib', detail=f'Invalid pyproject.toml: {e}', duration_s=time.time()-start)

        # Try pip install -e .
        # We only do this if pip is available and we have a valid manifest
        try:
            # Check if pip is available
            subprocess.run([self.python_executable, '-m', 'pip', '--version'], capture_output=True, timeout=5)

            # Run install
            cmd = [self.python_executable, '-m', 'pip', 'install', '-e', '.', '--no-deps', '--no-build-isolation']
            result = subprocess.run(cmd, cwd=workdir, capture_output=True, text=True, timeout=self.timeout_s)

            duration = time.time() - start
            if result.returncode != 0:
                # If it fails, it's a failure
                return GateResult(name='build', status=FAILED, method='pip', detail=f'pip install failed: {result.stderr[:500]}', duration_s=duration)

            return GateResult(name='build', status=PASSED, method='pip', detail='pip install -e . succeeded', duration_s=duration)

        except FileNotFoundError:
            # pip not found, skip
            return GateResult(name='build', status=SKIPPED, method='pip', detail='pip not available', duration_s=time.time()-start)
        except Exception as e:
            return GateResult(name='build', status=SKIPPED, method='pip', detail=f'Build check skipped: {e}', duration_s=time.time()-start)

    def _gate_smoke(self, workdir: str, python_files: List[str], authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Identify non-test modules
        # Test files usually have 'test' in name or are in tests/ dir
        non_test_modules = []
        for path in python_files:
            basename = os.path.basename(path).lower()
            if 'test' in basename or path.startswith('tests/') or path.startswith('test_'):
                continue
            # Convert path to module name
            # src/foo/bar.py -> foo.bar
            # foo/bar.py -> foo.bar
            clean_path = path
            if clean_path.startswith('src/'):
                clean_path = clean_path[4:]
            if clean_path.endswith('.py'):
                clean_path = clean_path[:-3]
            if clean_path.endswith('__init__'):
                clean_path = clean_path[:-9]

            module_name = clean_path.replace('/', '.').replace('\\', '.')
            if module_name:
                non_test_modules.append(module_name)

        if not non_test_modules:
            return GateResult(name='smoke', status=FAILED, method='subprocess', detail='No importable non-test modules found', duration_s=time.time()-start)

        # Construct PYTHONPATH
        env = os.environ.copy()
        pypath = [workdir, os.path.join(workdir, 'src')]
        env['PYTHONPATH'] = os.pathsep.join(pypath)

        # Try importing each module
        import_errors = []
        module_not_found_errors = []

        for module in non_test_modules:
            code = f"import {module}"
            try:
                result = subprocess.run(
                    [self.python_executable, '-c', code],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=10
                )
                if result.returncode != 0:
                    stderr = result.stderr
                    if 'ModuleNotFoundError' in stderr:
                        # Check if it's a third-party package or our own module
                        # If it's our own module failing to import due to missing deps, it's tricky.
                        # Spec: "If module imports fail solely with ModuleNotFoundError for uninstalled third-party packages... return SKIPPED"
                        # If it fails for other reasons, FAILED.
                        module_not_found_errors.append(f"{module}: {stderr.strip()}")
                    else:
                        import_errors.append(f"{module}: {stderr.strip()}")
            except Exception as e:
                import_errors.append(f"{module}: {e}")

        duration = time.time() - start

        if import_errors:
            return GateResult(name='smoke', status=FAILED, method='subprocess', detail='; '.join(import_errors), duration_s=duration)

        if module_not_found_errors:
            # If ALL failures are ModuleNotFoundError, we skip.
            # If some modules imported fine and others failed with MNE, we might still skip?
            # Spec: "If module imports fail solely with ModuleNotFoundError... return SKIPPED"
            # This implies if we can't verify because of missing deps, we skip.
            return GateResult(name='smoke', status=SKIPPED, method='subprocess', detail='Imports failed due to missing third-party packages', duration_s=duration)

        return GateResult(name='smoke', status=PASSED, method='subprocess', detail='All modules imported', duration_s=duration)

    def _gate_tests(self, workdir: str, python_files: List[str], authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Discover test files
        test_files = []
        for path in python_files:
            basename = os.path.basename(path).lower()
            if 'test' in basename:
                test_files.append(path)

        if not test_files:
            return GateResult(name='tests', status=FAILED, method='fs', detail='No test files found', duration_s=time.time()-start)

        env = os.environ.copy()
        pypath = [workdir, os.path.join(workdir, 'src')]
        env['PYTHONPATH'] = os.pathsep.join(pypath)

        # Try pytest first
        try:
            # Check if pytest is installed
            subprocess.run([self.python_executable, '-m', 'pytest', '--version'], capture_output=True, timeout=5)

            # Run pytest
            cmd = [self.python_executable, '-m', 'pytest', '-v', '--tb=short']
            result = subprocess.run(cmd, cwd=workdir, env=env, capture_output=True, text=True, timeout=self.timeout_s)

            duration = time.time() - start
            if result.returncode == 0:
                return GateResult(name='tests', status=PASSED, method='pytest', detail='All tests passed', duration_s=duration)
            else:
                # Check if it failed due to collection errors (missing deps)
                if 'ModuleNotFoundError' in result.stderr or 'ModuleNotFoundError' in result.stdout:
                    # If it's just missing deps, skip?
                    # Spec: 'If 0 tests are collected because of ModuleNotFoundError... return SKIPPED'
                    # If tests ran and failed, it's FAILED.
                    # If collection failed, it's SKIPPED.
                    if 'error' in result.stderr.lower() and 'collected 0' in result.stdout.lower():
                         return GateResult(name='tests', status=SKIPPED, method='pytest', detail='Tests not collected due to missing dependencies', duration_s=duration)

                return GateResult(name='tests', status=FAILED, method='pytest', detail=f'Tests failed: {result.stdout[-500:]}', duration_s=duration)

        except FileNotFoundError:
            pass # pytest not installed, fallback
        except Exception:
            pass # pytest failed to run, fallback

        # Stdlib fallback
        # We need to run a script that imports test files and runs unittest + bare functions
        # This is complex to do in a single subprocess call without writing a runner script.
        # Let's write a temporary runner script.

        runner_code = '''
    import sys
    import unittest
    import importlib
    import os
    import inspect

    # Add paths
    sys.path.insert(0, os.getcwd())
    sys.path.insert(0, os.path.join(os.getcwd(), 'src'))

    test_files = []
    for root, dirs, files in os.walk('.'):
    for f in files:
        if 'test' in f.lower() and f.endswith('.py'):
            test_files.append(os.path.join(root, f))

    loader = unittest.TestLoader()
    suite = unittest.TestSuite()

    # Collect bare test functions
    bare_tests = []

    for tf in test_files:
    # Convert path to module name
    rel_path = os.path.relpath(tf, '.')
    mod_name = rel_path.replace(os.sep, '.').replace('/', '.').replace('.py', '')
    if mod_name.startswith('src.'):
        mod_name = mod_name[4:]

    try:
        mod = importlib.import_module(mod_name)

        # Add unittest classes
        suite.addTests(loader.loadTestsFromModule(mod))

        # Add bare test functions
        for attr_name in dir(mod):
            if attr_name.startswith('test_'):
                attr = getattr(mod, attr_name)
                if callable(attr):
                    # Check if it takes 0 args
                    try:
                        sig = inspect.signature(attr)
                        # If it has no parameters, or all parameters have defaults, it can be called with 0 args
                        # But strictly speaking, bare test functions usually take 0 args.
                        # We check if it can be called with 0 args.
                        if len(sig.parameters) == 0:
                            bare_tests.append((mod_name, attr_name, attr))
                    except (ValueError, TypeError):
                        # If signature inspection fails, assume it might be callable with 0 args if it's a simple function
                        # But safer to skip if we can't verify, or try to call it?
                        # Let's just skip if we can't inspect, or assume 0 args if it's a function?
                        # The bug was likely that it wasn't finding them at all.
                        pass

    except ModuleNotFoundError as e:
        print(f'SKIP: {mod_name}: {e}')
        continue
    except Exception as e:
        print(f'ERROR: {mod_name}: {e}')
        continue

    # Run unittest suite
    runner = unittest.TextTestRunner(verbosity=2)
    result = runner.run(suite)

    # Run bare tests
    bare_passed = 0
    bare_failed = 0
    for mod_name, attr_name, func in bare_tests:
    try:
        func()
        bare_passed += 1
        print(f'PASS: {mod_name}.{attr_name}')
    except Exception as e:
        bare_failed += 1
        print(f'FAIL: {mod_name}.{attr_name}: {e}')

    if result.wasSuccessful() and bare_failed == 0:
    sys.exit(0)
    else:
    sys.exit(1)
    '''

        try:
            result = subprocess.run(
                [self.python_executable, '-c', runner_code],
                cwd=workdir,
                env=env,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )

            duration = time.time() - start

            if result.returncode == 0:
                return GateResult(name='tests', status=PASSED, method='stdlib', detail='All tests passed (stdlib)', duration_s=duration)
            else:
                # Check for skip conditions
                if 'SKIP:' in result.stdout and 'collected 0' not in result.stdout:
                     # If we skipped some but ran others, and others failed, it's FAILED.
                     # If we skipped ALL, it's SKIPPED.
                     if 'ERROR:' not in result.stdout and 'FAIL:' not in result.stdout:
                         return GateResult(name='tests', status=SKIPPED, method='stdlib', detail='Tests skipped due to missing dependencies', duration_s=duration)

                return GateResult(name='tests', status=FAILED, method='stdlib', detail=f'Tests failed: {result.stdout[-500:]}', duration_s=duration)

        except Exception as e:
            return GateResult(name='tests', status=SKIPPED, method='stdlib', detail=f'Test runner error: {e}', duration_s=time.time()-start)

    def _gate_telemetry(self, python_files: List[str], authored: Dict[str, str]) -> GateResult:
        start = time.time()

        if not python_files:
            return GateResult(name='telemetry', status=FAILED, method='ast', detail='No python files to analyze', duration_s=time.time()-start)

        has_import = False
        has_call = False

        tracer_methods = {
            'start_as_current_span', 'start_span', 'get_tracer', 
            'get_tracer_provider', 'set_tracer_provider', 'get_meter'
        }

        for path in python_files:
            content = authored[path]
            try:
                tree = ast.parse(content, filename=path)
            except SyntaxError:
                continue

            for node in ast.walk(tree):
                # Check for import opentelemetry
                if isinstance(node, ast.Import):
                    for alias in node.names:
                        if alias.name == 'opentelemetry' or alias.name.startswith('opentelemetry.'):
                            has_import = True
                elif isinstance(node, ast.ImportFrom):
                    if node.module == 'opentelemetry' or (node.module and node.module.startswith('opentelemetry.')):
                        has_import = True

                # Check for calls
                if isinstance(node, ast.Call):
                    func_name = None
                    if isinstance(node.func, ast.Name):
                        func_name = node.func.id
                    elif isinstance(node.func, ast.Attribute):
                        func_name = node.func.attr

                    if func_name in tracer_methods:
                        has_call = True

        duration = time.time() - start

        if has_import and has_call:
            return GateResult(name='telemetry', status=PASSED, method='ast', detail='Telemetry instrumentation found', duration_s=duration)

        if not has_import:
            return GateResult(name='telemetry', status=FAILED, method='ast', detail='No opentelemetry import found', duration_s=duration)

        if not has_call:
            return GateResult(name='telemetry', status=FAILED, method='ast', detail='Import found but no tracer/span calls', duration_s=duration)

        return GateResult(name='telemetry', status=FAILED, method='ast', detail='Unknown telemetry state', duration_s=duration)

